def transform(grid):
    """Replace large, solid monochrome rectangular patches with color 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marked = [[False] * w for _ in range(h)]
    # A target patch is at least 5x5. For each color and vertical span,
    # mark contiguous columns that have that color throughout the span.
    for top in range(h):
        for color in set(grid[top]):
            valid = [True] * w
            for bottom in range(top, h):
                valid = [valid[c] and grid[bottom][c] == color for c in range(w)]
                height = bottom - top + 1
                if height >= 5:
                    c = 0
                    while c < w:
                        if valid[c]:
                            start = c
                            while c < w and valid[c]:
                                c += 1
                            if c - start >= 5:
                                for r in range(top, bottom + 1):
                                    for x in range(start, c):
                                        marked[r][x] = True
                        else:
                            c += 1
    for r in range(h):
        for c in range(w):
            if marked[r][c]:
                out[r][c] = 4
    return out

